# 050 - l'expander bloccato non blocca il programma

import sys


def traccia(testo):
    riga = '[050] %s' % testo
    try:
        print(riga)
    except Exception:
        pass
    try:
        import datetime
        import os
        d = os.path.join(os.environ.get('LOCALAPPDATA') or
                         os.path.expanduser('~'), 'KaraDom')
        os.makedirs(d, exist_ok=True)
        with open(os.path.join(d, 'patch050.log'), 'a', encoding='utf-8') as f:
            f.write('%s  %s%s' % (
                datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                riga, chr(10)))
    except Exception:
        pass


CODICE_EXP = '# -*- coding: utf-8 -*-\n"""\nExpander MIDI hardware per KaraDom (M-Live X-Light 4 e simili).\n================================================================\n\nCOSA FA\n    Se al PC è collegato un expander MIDI (es. M-Live X-Light 4), KaraDom smette\n    di suonare i file MIDI con il SoundFont interno e manda i messaggi MIDI\n    all\'expander: le basi suonano con i suoni dell\'expander e l\'audio esce dalle\n    sue uscite. Il testo karaoke, la sincronizzazione, il mixer, il pitch e la\n    velocità continuano a funzionare identici (il motore di timing è lo stesso).\n\nCOME DECIDE (config \'expander_mode\' nel DB):\n    \'auto\' (default) → se trova un expander lo usa, altrimenti SoundFont interno\n    \'off\'            → non usa MAI l\'expander, anche se collegato\n    \'on\'             → usa sempre la porta salvata in \'expander_port\'\n\nPERCHÉ È UN MODULO A PARTE\n    Tutto il codice nuovo vive qui. Negli altri file ci sono solo 3 innesti da\n    poche righe, marcati con "EXPANDER MIDI". Per tornare indietro basta\n    impostare expander_mode=\'off\' (nessun rischio) oppure togliere gli innesti.\n\nBACKEND\n    Uscita MIDI via winmm (ctypes, incluso in Windows): nessuna DLL o pacchetto\n    aggiuntivo da includere nel build Nuitka. Fallback a python-rtmidi se c\'è.\n"""\n\nimport os\nimport sys\nimport ctypes\nimport threading\n\nfrom .expander_sounds import nome_suono as _nome_suono_xlight\n\n# ===================================================================\n#  CONFIGURAZIONE (chiavi nel DB config di KaraDom)\n# ===================================================================\n\nCFG_MODE = \'expander_mode\'      # \'auto\' | \'off\' | \'on\'\nCFG_PORT = \'expander_port\'      # nome della porta MIDI da usare in modo \'on\'\nCFG_SYSEX = \'expander_sysex\'    # \'1\' = inoltra i SysEx del file all\'expander\n\n\ndef _cfg(chiave, default=\'\'):\n    try:\n        from .database import Database\n        val = Database.get_config(chiave, default)\n        return val if val not in (None, \'\') else default\n    except Exception:\n        return default\n\n\ndef _set_cfg(chiave, valore):\n    try:\n        from .database import Database\n        Database.set_config(chiave, valore)\n        return True\n    except Exception as e:\n        print(f"⚠️ Expander: impossibile salvare \'{chiave}\': {e}")\n        return False\n\n\ndef get_mode():\n    """Modalità corrente: \'auto\' | \'off\' | \'on\'"""\n    mode = str(_cfg(CFG_MODE, \'auto\')).lower().strip()\n    return mode if mode in (\'auto\', \'off\', \'on\') else \'auto\'\n\n\ndef set_mode(mode):\n    if mode not in (\'auto\', \'off\', \'on\'):\n        mode = \'auto\'\n    return _set_cfg(CFG_MODE, mode)\n\n\ndef sysex_abilitato():\n    return str(_cfg(CFG_SYSEX, \'1\')).strip() not in (\'0\', \'no\', \'false\')\n\n\ndef stream_abilitato():\n    """Interruttore dello stream MIDI (acceso salvo diversa indicazione).\n\n    Serve una via d\'uscita che non passi da una nuova build: gli expander sono\n    hardware di marche diverse, e se su un modello il driver accettasse lo\n    stream senza poi suonarlo come si deve, si spegne questa e si torna\n    all\'invio diretto di prima.\n\n        UPDATE config SET valore=\'0\' WHERE chiave=\'expander_stream\';\n    """\n    return str(_cfg(\'expander_stream\', \'1\')).strip() not in (\'0\', \'no\', \'false\')\n\n\n# ===================================================================\n#  RICONOSCIMENTO PORTE MIDI\n# ===================================================================\n\n# Synth software: NON sono expander (ne\' su Windows ne\' su Linux)\n_PATTERN_SOFTWARE = (\n    \'microsoft gs wavetable\', \'wavetable synth\', \'microsoft midi mapper\',\n    \'general midi ds\', \'gs wavetable\',\n    # Linux: sintetizzatori software che espongono una porta MIDI. Sceglierli\n    # come \'expander\' scavalcherebbe il nostro FluidSynth (e il SoundFont).\n    \'fluidsynth\', \'fluid synth\', \'timidity\', \'qsynth\',\n)\n\n# Porte virtuali/loopback: NON sono expander\n_PATTERN_LOOPBACK = (\n    \'loopmidi\', \'loopbe\', \'midi yoke\', \'maple\', \'virtual\', \'virtualmidi\',\n    \'rtpmidi\', \'bome\', \'copperlan\', \'ipmidi\', \'sforzando\',\n    # Linux: \'Midi Through\' e\' la porta virtuale che ALSA crea SEMPRE. Non\n    # suona nulla: chi ci manda le note non sente niente. Senza questa riga\n    # finiva nel ramo finale (= expander sconosciuto, punteggio 10) ed era\n    # l\'unica porta presente, quindi veniva scelta d\'ufficio in modo \'auto\'.\n    \'midi through\', \'through port\',\n)\n\n# Mixer e schede audio: espongono una porta MIDI per il CONTROLLO REMOTO\n# (scene, fader, mute), NON hanno generatore sonoro. Mandarci il MIDI di una\n# base = nessun suono, e i program change possono persino cambiare le scene\n# del mixer. Non vanno mai scelti come expander.\n_PATTERN_MIXER_AUDIO = (\n    \'xr18\', \'xr16\', \'xr12\', \'x18\', \'x32\', \'x-air\', \'xair\', \'x-touch\', \'xtouch\',\n    \'behringer\', \'midas\', \'soundcraft\', \'allen & heath\', \'allen&heath\', \'qu-\',\n    \'focusrite\', \'scarlett\', \'presonus\', \'audiobox\', \'studiolive\',\n    \'motu\', \'tascam\', \'zoom u\', \'zoom h\', \'audient\', \'ssl 2\', \'rme\', \'babyface\',\n    \'fireface\', \'steinberg ur\', \'ur22\', \'ur44\', \'ur12\', \'audio interface\',\n)\n\n# Nomi che identificano con certezza un expander (punteggio alto)\n_PATTERN_EXPANDER_NOTO = (\n    \'xlight\', \'x-light\', \'x light\', \'m-live\', \'mlive\', \'m live\',\n    \'merish\', \'okyweb\', \'ketron\', \'audya\', \'expander\',\n)\n\n# Moduli sonori hardware comuni (punteggio medio)\n_PATTERN_MODULO = (\n    \'sound module\', \'sound canvas\', \'roland\', \'edirol\', \'yamaha\', \'korg\',\n    \'motif\', \'integra\', \'sd-\', \'sd90\', \'mu100\', \'mu128\', \'usb midi\',\n    \'usb-midi\', \'usb2.0-midi\', \'umc\', \'midisport\',\n)\n\n\ndef classifica_porta(nome):\n    """\'software\' | \'loopback\' | \'mixer\' | \'expander\' — che cos\'è questa porta.\n\n    NB: un expander RICONOSCIUTO vince sempre (ci sono mixer e moduli sonori\n    della stessa marca: se il nome dice che e\' un expander, e\' un expander)."""\n    n = (nome or \'\').lower()\n    if any(p in n for p in _PATTERN_EXPANDER_NOTO):\n        return \'expander\'\n    if any(p in n for p in _PATTERN_SOFTWARE):\n        return \'software\'\n    if any(p in n for p in _PATTERN_LOOPBACK):\n        return \'loopback\'\n    if any(p in n for p in _PATTERN_MIXER_AUDIO):\n        return \'mixer\'\n    return \'expander\'\n\n\ndef _punteggio(nome):\n    """Quanto è probabile che sia l\'expander da usare (0 = da scartare)."""\n    n = (nome or \'\').lower()\n    if classifica_porta(nome) != \'expander\':\n        return 0\n    if any(p in n for p in _PATTERN_EXPANDER_NOTO):\n        return 100\n    if any(p in n for p in _PATTERN_MODULO):\n        return 50\n    return 10          # hardware sconosciuto: comunque un candidato\n\n\ndef list_ports():\n    """Elenco porte MIDI OUT: [{\'id\', \'nome\', \'tipo\', \'punteggio\'}]"""\n    porte = []\n    for idx, nome in _backend_list():\n        porte.append({\n            \'id\': idx,\n            \'nome\': nome,\n            \'tipo\': classifica_porta(nome),\n            \'punteggio\': _punteggio(nome),\n        })\n    return porte\n\n\ndef detect_expander():\n    """Porta dell\'expander da usare, o None.\n\n    Rispetta la modalità: \'off\' → sempre None; \'on\' → la porta salvata;\n    \'auto\' → il candidato hardware col punteggio più alto.\n    """\n    mode = get_mode()\n    if mode == \'off\':\n        return None\n\n    porte = list_ports()\n    if not porte:\n        return None\n\n    if mode == \'on\':\n        voluta = str(_cfg(CFG_PORT, \'\')).strip().lower()\n        if voluta:\n            for p in porte:\n                if p[\'nome\'].strip().lower() == voluta:\n                    return p\n            # la porta salvata non c\'è più: ripiega sull\'automatico\n            print(f"⚠️ Expander: porta \'{voluta}\' non trovata, provo il rilevamento automatico")\n            # NB: se la porta salvata c\'e\', viene restituita sopra anche se e\'\n            # un mixer: scelta esplicita dell\'utente, si rispetta.\n\n    candidati = [p for p in porte if p[\'punteggio\'] > 0]\n    if not candidati:\n        return None\n    candidati.sort(key=lambda p: (-p[\'punteggio\'], p[\'id\']))\n    return candidati[0]\n\n\n# ===================================================================\n#  BACKEND USCITA MIDI — winmm (ctypes) con fallback python-rtmidi\n# ===================================================================\n\n_MMSYSERR_NOERROR = 0\n_MIDIERR_STILLPLAYING = 65\n\n\nclass _MIDIOUTCAPSW(ctypes.Structure):\n    _fields_ = [\n        (\'wMid\', ctypes.c_ushort),\n        (\'wPid\', ctypes.c_ushort),\n        (\'vDriverVersion\', ctypes.c_uint),\n        (\'szPname\', ctypes.c_wchar * 32),\n        (\'wTechnology\', ctypes.c_ushort),\n        (\'wVoices\', ctypes.c_ushort),\n        (\'wNotes\', ctypes.c_ushort),\n        (\'wChannelMask\', ctypes.c_ushort),\n        (\'dwSupport\', ctypes.c_ulong),\n    ]\n\n\nclass _MIDIHDR(ctypes.Structure):\n    _fields_ = [\n        (\'lpData\', ctypes.c_char_p),\n        (\'dwBufferLength\', ctypes.c_ulong),\n        (\'dwBytesRecorded\', ctypes.c_ulong),\n        (\'dwUser\', ctypes.c_size_t),\n        (\'dwFlags\', ctypes.c_ulong),\n        (\'lpNext\', ctypes.c_void_p),\n        (\'reserved\', ctypes.c_size_t),\n        (\'dwOffset\', ctypes.c_ulong),\n        (\'dwReserved\', ctypes.c_size_t * 8),\n    ]\n\n\ndef _winmm():\n    if sys.platform != \'win32\':\n        return None\n    try:\n        return ctypes.windll.winmm\n    except Exception:\n        return None\n\n\ndef _backend_list():\n    """[(id, nome)] delle porte MIDI OUT disponibili."""\n    mm = _winmm()\n    if mm:\n        try:\n            porte = []\n            for i in range(mm.midiOutGetNumDevs()):\n                caps = _MIDIOUTCAPSW()\n                if mm.midiOutGetDevCapsW(i, ctypes.byref(caps),\n                                         ctypes.sizeof(caps)) == _MMSYSERR_NOERROR:\n                    porte.append((i, caps.szPname))\n            if porte:\n                return porte\n        except Exception as e:\n            print(f"⚠️ Expander: enumerazione winmm fallita: {e}")\n\n    try:                                    # fallback: python-rtmidi\n        import rtmidi\n        out = rtmidi.MidiOut()\n        porte = list(enumerate(out.get_ports()))\n        del out\n        return porte\n    except Exception:\n        return []\n\n\nclass _UscitaMIDI:\n    """Porta MIDI OUT aperta. Thread-safe, non solleva eccezioni in riproduzione."""\n\n    def __init__(self, device_id, nome):\n        self.device_id = device_id\n        self.nome = nome\n        self.aperta = False\n        self._mm = None\n        self._handle = None\n        self._rtmidi = None\n        self._stream = None\n        self._lock = threading.Lock()\n        self._errori = 0\n        self._morta = False        # il driver non risponde: si smette di usarla\n\n    # ------------------------------------------------------------------\n    # ⛔⛔ IL PROGRAMMA NON DEVE MAI RESTARE APPESO AL DRIVER MIDI.\n    #     Segnalazione del cliente (13-09): con l\'expander attaccato KaraDom\n    #     si BLOCCA. Le chiamate winmm (`midiOutOpen`, `midiOutReset`,\n    #     `midiOutClose`) girano sul filo del programma e, se il driver non\n    #     risponde - expander spento a meta\', USB staccata, porta gia\' presa\n    #     da un altro programma - non tornano piu\': la finestra si inchioda e\n    #     non c\'e\' niente da fare.\n    #     Regola dell\'utente, testuale: «d\'accordo non comincia, ma non deve\n    #     frizzarsi». Quindi: ogni chiamata al driver ha un ORE\n    #     LIMITE; se scade si rinuncia alla porta e il programma continua.\n    # ------------------------------------------------------------------\n    ATTESA_APERTURA = 3.0          # secondi buoni per aprire la porta\n    ATTESA_CHIUSURA = 1.5          # chiudere deve essere svelto\n\n    def _con_orologio(self, cosa, fn, secondi):\n        """Chiama il driver in un filo a parte: se non risponde, si rinuncia.\n\n        Torna il risultato, oppure None se e\' scaduto il tempo. In quel caso\n        la porta viene dichiarata MORTA: da li\' in poi non le si manda piu\'\n        niente, cosi\' un driver appeso non trascina giu\' tutto il programma.\n        """\n        esito = {}\n\n        def lavora():\n            try:\n                esito[\'ok\'] = fn()\n            except Exception as e:\n                esito[\'err\'] = e\n\n        t = threading.Thread(target=lavora, daemon=True,\n                             name=\'expander-%s\' % cosa)\n        t.start()\n        t.join(secondi)\n        if t.is_alive():\n            self._morta = True\n            self.aperta = False\n            print("⚠️ Expander: \'%s\' non risponde da %.1f s sulla porta \'%s\': "\n                  "la lascio stare e vado avanti (il programma NON si blocca)"\n                  % (cosa, secondi, self.nome))\n            return None\n        if \'err\' in esito:\n            raise esito[\'err\']\n        return esito.get(\'ok\')\n\n    def apri(self):\n        # ⏱️ PRIMA SI PROVA LO STREAM DI WINDOWS.\n        #\n        # Con l\'invio diretto e\' Python a decidere l\'istante di ogni nota, e\n        # quando il programma e\' occupato - la ricerca fra 400.000 basi e\'\n        # l\'esempio vero - quell\'istante arriva tardi: misurato, fino a 445 ms\n        # su una singola nota, ed e\' il "rallentamento dei BPM" che si sente\n        # con l\'expander. Con lo stream le note si consegnano al driver in\n        # anticipo, con scritto sopra quando devono uscire: le fa uscire lui,\n        # e il programma occupato non le tocca piu\' (misurato: 18 ms di scarto\n        # in 10 secondi, contro 253 ms).\n        #\n        # Se lo stream non si apre - driver che non lo sostiene, porta occupata -\n        # si prosegue esattamente come prima. Non e\' una sostituzione: e\' una\n        # strada in piu\' che, se c\'e\', si preferisce.\n        try:\n            if not stream_abilitato():\n                raise RuntimeError("spento dalle impostazioni")\n            from moduli.midi_stream import UscitaStream\n            st = UscitaStream(self.device_id, self.nome)\n            if st.apri_a_millisecondi():\n                self._stream = st\n                self._mm = _winmm()\n                self._handle = st._h      # i messaggi immediati passano di qui\n                self.aperta = True\n                return True\n        except Exception as e:\n            print("🎹 Expander: stream non utilizzabile (%s), uso l\'invio diretto" % e)\n        self._stream = None\n\n        mm = _winmm()\n        if mm is not None:\n            handle = ctypes.c_void_p()\n            # ⏱️ con l\'orologio: un expander bloccato non deve inchiodare qui\n            rc = self._con_orologio(\n                \'apertura della porta\',\n                lambda: mm.midiOutOpen(ctypes.byref(handle), self.device_id,\n                                       0, 0, 0),\n                self.ATTESA_APERTURA)\n            if rc is None:\n                return False           # scaduto: si rinuncia all\'expander\n            if rc == _MMSYSERR_NOERROR:\n                self._mm, self._handle, self.aperta = mm, handle, True\n                print(f"🎹 Expander: porta MIDI aperta → {self.nome}")\n                return True\n            print(f"⚠️ Expander: midiOutOpen ha risposto {rc} su \'{self.nome}\'")\n\n        try:                                # fallback rtmidi\n            import rtmidi\n            self._rtmidi = rtmidi.MidiOut()\n            self._rtmidi.open_port(self.device_id)\n            self.aperta = True\n            print(f"🎹 Expander: porta MIDI aperta (rtmidi) → {self.nome}")\n            return True\n        except Exception as e:\n            print(f"❌ Expander: impossibile aprire \'{self.nome}\': {e}")\n            self._rtmidi = None\n            return False\n\n    # ---------- invio ----------\n\n    def short(self, status, dato1=0, dato2=0, istante=None):\n        """Messaggio MIDI da 2-3 byte (note, CC, program change, pitch bend).\n\n        `istante` e\' il momento - letto su time.perf_counter - in cui il\n        messaggio deve USCIRE. Quando c\'e\', e lo stream e\' aperto, il messaggio\n        viene consegnato al driver con quell\'orario scritto sopra e non parte\n        da qui: e\' quello che tiene fermo il tempo mentre il programma e\'\n        occupato. Senza `istante` esce subito, com\'e\' sempre stato - e\' la\n        strada dei comandi che non hanno un tempo musicale (reset, volume,\n        pannello dei canali).\n        """\n        if not self.aperta or self._morta:\n            return\n        try:\n            if istante is not None and self._stream is not None:\n                self._stream.programma([(istante, status, dato1, dato2)])\n                return\n            # ⏱️ il lucchetto NON si aspetta all\'infinito: se chi ce l\'ha e\'\n            #    appeso dentro il driver, qui si rinuncia alla nota e si\n            #    torna subito. Una nota persa non si nota, un programma\n            #    inchiodato si\'.\n            if not self._lock.acquire(timeout=0.2):\n                self._segnala(RuntimeError(\'la porta MIDI non risponde\'))\n                return\n            try:\n                if self._mm is not None and self._handle is not None:\n                    msg = (status & 0xFF) | ((dato1 & 0x7F) << 8) | ((dato2 & 0x7F) << 16)\n                    self._mm.midiOutShortMsg(self._handle, ctypes.c_ulong(msg))\n                elif self._rtmidi is not None:\n                    self._rtmidi.send_message([status & 0xFF, dato1 & 0x7F, dato2 & 0x7F])\n            finally:\n                self._lock.release()\n        except Exception as e:\n            self._segnala(e)\n\n    def sysex(self, dati, istante=None):\n        """SysEx completo, compresi F0 iniziale e F7 finale.\n\n        `istante` come in short(): serve ai cambi di banco che stanno DENTRO il\n        brano, che devono uscire al momento giusto e non in coda a quello che\n        e\' gia\' programmato - se no il timbro cambia con un ritardo che si\n        sente. I SysEx di servizio (reset, volume) non ce l\'hanno ed escono\n        subito.""" \n        if not self.aperta or self._morta or not dati:\n            return\n        try:\n            buf = bytes(dati)\n            if buf[0] != 0xF0:\n                buf = b\'\\xF0\' + buf\n            if buf[-1] != 0xF7:\n                buf = buf + b\'\\xF7\'\n\n            if self._stream is not None:\n                # ⚠️ Sull\'handle di uno stream `midiOutLongMsg` risponde\n                # RIFIUTATO (provato: codice 8). I SysEx vanno messi dentro lo\n                # stream come tutti gli altri messaggi - ed e\' importante che\n                # ci arrivino, perche\' sono loro a scegliere i banchi M-Live.\n                if istante is not None:\n                    self._stream.programma([(istante, "sysex", buf)])\n                else:\n                    self._stream.accoda([(0, "sysex", buf)])\n                    self._stream.parti()   # se era fermo, deve uscire adesso\n                return\n\n            if not self._lock.acquire(timeout=0.2):\n                self._segnala(RuntimeError(\'la porta MIDI non risponde\'))\n                return\n            try:\n                if self._mm is not None and self._handle is not None:\n                    hdr = _MIDIHDR()\n                    hdr.lpData = ctypes.c_char_p(buf)\n                    hdr.dwBufferLength = len(buf)\n                    hdr.dwFlags = 0\n                    if self._mm.midiOutPrepareHeader(self._handle, ctypes.byref(hdr),\n                                                     ctypes.sizeof(hdr)) != _MMSYSERR_NOERROR:\n                        return\n                    self._mm.midiOutLongMsg(self._handle, ctypes.byref(hdr), ctypes.sizeof(hdr))\n                    # il driver copia subito il buffer: basta un unprepare best-effort\n                    for _ in range(50):\n                        if self._mm.midiOutUnprepareHeader(\n                                self._handle, ctypes.byref(hdr),\n                                ctypes.sizeof(hdr)) != _MIDIERR_STILLPLAYING:\n                            break\n                elif self._rtmidi is not None:\n                    self._rtmidi.send_message(list(buf))\n            finally:\n                self._lock.release()\n        except Exception as e:\n            self._segnala(e)\n\n    def _segnala(self, e):\n        self._errori += 1\n        if self._errori <= 3:\n            print(f"⚠️ Expander: errore invio MIDI ({e})")\n        elif self._errori == 4:\n            print("⚠️ Expander: altri errori di invio — messaggi successivi silenziati")\n\n    def chiudi(self):\n        st, self._stream = self._stream, None\n        if st is not None:\n            # lo stream possiede l\'handle: lo chiude lui, e sotto non si deve\n            # richiudere lo stesso handle una seconda volta\n            try:\n                st.ferma()\n                st.chiudi()\n            except Exception:\n                pass\n            self._handle = None\n            self.aperta = False\n            return\n\n        # ⏱️ anche chiudere puo\' restare appeso a un expander bloccato: se non\n        #    risponde si lascia perdere l\'handle e si va avanti. Meglio una\n        #    porta non chiusa bene che un programma che non si chiude piu\'.\n        preso = self._lock.acquire(timeout=1.0)\n        try:\n            if self._mm is not None and self._handle is not None:\n                self._con_orologio(\'chiusura della porta\',\n                                   lambda: (self._mm.midiOutReset(self._handle),\n                                            self._mm.midiOutClose(self._handle)),\n                                   self.ATTESA_CHIUSURA)\n            elif self._rtmidi is not None:\n                self._con_orologio(\'chiusura della porta\',\n                                   self._rtmidi.close_port,\n                                   self.ATTESA_CHIUSURA)\n        except Exception:\n            pass\n        finally:\n            if preso:\n                try:\n                    self._lock.release()\n                except Exception:\n                    pass\n            self._mm = self._handle = self._rtmidi = None\n            self.aperta = False\n\n\n# ===================================================================\n#  PROXY "SYNTH": stessa API di pyfluidsynth, ma verso l\'expander\n# ===================================================================\n\nclass _SynthExpander:\n    """Finto oggetto FluidSynth: il playback loop di FluidSynthPlayer chiama\n    questi metodi credendo di parlare col synth software, invece i messaggi\n    finiscono sulla porta MIDI dell\'expander.\n\n    È il cuore del trucco: così NON si duplica il motore di timing, e testo,\n    seek, mute, pitch e velocità restano identici al percorso interno."""\n\n    # Quando il player lavora in ANTICIPO (solo con lo stream) qui dentro\n    # scrive, prima di ogni messaggio, il momento in cui quel messaggio deve\n    # uscire. Se resta None - synth software, o stream non disponibile - tutto\n    # parte subito come e\' sempre stato.\n    istante = None\n\n    def __init__(self, uscita, player):\n        self.out = uscita\n        self.player = player            # per leggere i bank MSB/LSB reali\n\n    # --- note ---\n    def noteon(self, ch, key, vel):\n        self.out.short(0x90 | (ch & 0x0F), key, vel, istante=self.istante)\n\n    def noteoff(self, ch, key):\n        self.out.short(0x80 | (ch & 0x0F), key, 0, istante=self.istante)\n\n    # --- controlli ---\n    def cc(self, ch, num, val):\n        self.out.short(0xB0 | (ch & 0x0F), num, val, istante=self.istante)\n\n    def pitch_bend(self, ch, val):\n        val = max(0, min(16383, int(val)))\n        self.out.short(0xE0 | (ch & 0x0F), val & 0x7F, (val >> 7) & 0x7F, istante=self.istante)\n\n    def channel_pressure(self, ch, val):\n        self.out.short(0xD0 | (ch & 0x0F), val, 0, istante=self.istante)\n\n    def key_pressure(self, ch, key, val):\n        self.out.short(0xA0 | (ch & 0x0F), key, val, istante=self.istante)\n\n    def program_change(self, ch, prog):\n        self.out.short(0xC0 | (ch & 0x0F), prog, 0, istante=self.istante)\n\n    def program_select(self, ch, sfid, bank, preset):\n        """Bank Select + Program Change verso l\'expander.\n\n        FluidSynth usa il banco 128 per indicare le percussioni: è una\n        convenzione interna del SoundFont, l\'hardware non la conosce. Sul\n        canale 10 si manda quindi il bank MSB vero del file (0 se assente)."""\n        ch = ch & 0x0F\n        try:\n            msb = self.player.channel_bank_msb[ch]\n            lsb = self.player.channel_bank_lsb[ch]\n        except Exception:\n            msb, lsb = 0, 0\n\n        if bank == 128:                 # canale percussioni\n            msb_out = msb\n        else:\n            msb_out = bank if bank is not None else msb\n\n        self.out.short(0xB0 | ch, 0, msb_out & 0x7F, istante=self.istante)\n        self.out.short(0xB0 | ch, 32, lsb & 0x7F, istante=self.istante)\n        self.out.short(0xC0 | ch, preset & 0x7F, 0, istante=self.istante)\n\n    def sysex(self, dati):\n        self.out.sysex(dati, istante=self.istante)\n\n    # --- API FluidSynth che qui non hanno senso: assorbite senza effetti ---\n    def setting(self, *a, **k):\n        return None\n\n    def set_reverb(self, *a, **k):\n        return None                     # riverbero/chorus li fa l\'expander\n\n    def set_chorus(self, *a, **k):\n        return None\n\n    def set_interp_method(self, *a, **k):\n        return None\n\n    def sfload(self, *a, **k):\n        return 0\n\n    def sfunload(self, *a, **k):\n        return None\n\n    def sfpreset_name(self, sfid, bank, preset):\n        """Nome del suono: lo prende dalla lista dell\'expander, non dal SoundFont."""\n        return nome_suono_expander(preset, bank, is_drum=(bank == 128))\n\n    def system_reset(self):\n        for ch in range(16):\n            self.cc(ch, 120, 0)\n            self.cc(ch, 121, 0)\n\n    def start(self, *a, **k):\n        return None\n\n    def delete(self):\n        try:\n            self.out.chiudi()\n        except Exception:\n            pass\n\n\n# ===================================================================\n#  NOMI DEI SUONI (per il mixer MIDI)\n# ===================================================================\n\n_tabella_nomi = None        # override opzionale per altri expander\n\n\ndef set_sound_table(funzione):\n    """Sostituisce la lista suoni: funzione(program, bank_msb, is_drum) -> nome/None.\n    Serve se un domani si aggiunge un expander diverso dall\'X-Light 4."""\n    global _tabella_nomi\n    _tabella_nomi = funzione\n\n\ndef nome_suono_expander(program, bank_msb=0, is_drum=False):\n    """Nome del suono così come si chiama SULL\'EXPANDER (X-Light 4 di default).\n    Ritorna None se sconosciuto, così il chiamante può ripiegare sui nomi GM."""\n    try:\n        if bank_msb == 128:             # convenzione FluidSynth = percussioni\n            bank_msb, is_drum = 0, True\n        if _tabella_nomi is not None:\n            return _tabella_nomi(program, bank_msb, is_drum)\n        return _nome_suono_xlight(program, bank_msb, is_drum)\n    except Exception:\n        return None\n\n\n# ===================================================================\n#  PLAYER\n# ===================================================================\n\ndef _classe_base():\n    from .fluidsynth_player import FluidSynthPlayer\n    return FluidSynthPlayer\n\n\nclass ExpanderPlayer(object):\n    """Segnaposto: la classe vera viene costruita a runtime da _crea_classe(),\n    per non importare fluidsynth_player al caricamento del modulo."""\n    pass\n\n\ndef _crea_classe():\n    """Costruisce ExpanderPlayer come sottoclasse di FluidSynthPlayer.\n\n    Eredita TUTTO il motore (tempo map, timing, seek, mute, pitch, speed):\n    qui si sostituisce solo la destinazione dei messaggi."""\n    Base = _classe_base()\n\n    class _ExpanderPlayer(Base):\n\n        is_expander = True\n\n        def __init__(self, porta):\n            precedente = Base._instance      # non rubare il singleton FluidSynth\n            super().__init__()\n            Base._instance = precedente\n\n            self.porta = porta\n            self.out = None\n            self.nome_porta = porta.get(\'nome\', \'?\')\n\n        # ---------- avvio ----------\n\n        def initialize(self, soundfont_path=None):\n            """Apre la porta MIDI. Nessun SoundFont, nessun driver audio."""\n            try:\n                self.out = _UscitaMIDI(self.porta[\'id\'], self.nome_porta)\n                if not self.out.apri():\n                    self.out = None\n                    return False\n\n                self.synth = _SynthExpander(self.out, self)\n                # sfid != None: il playback loop manda i program change solo se c\'è\n                self.sfid = 0\n                self.soundfont_path = None\n\n                self.out.sysex(b\'\\xF0\\x7E\\x7F\\x09\\x01\\xF7\')     # GM System On\n                for ch in range(16):\n                    self.synth.cc(ch, 120, 0)\n                    self.synth.cc(ch, 121, 0)\n\n                self.initialized = True\n                print(f"✅ Expander MIDI attivo: {self.nome_porta} "\n                      f"(SoundFont interno disattivato)")\n                return True\n            except Exception as e:\n                print(f"❌ Expander: inizializzazione fallita: {e}")\n                self.initialized = False\n                return False\n\n        # ---------- adattamenti ----------\n\n        def _set_interpolation(self, method):\n            return None                  # roba da synth software\n\n        def set_master_gain(self, gain):\n            """Volume generale via SysEx GM Master Volume (l\'expander non ha \'gain\')."""\n            self._master_gain = max(0.0, min(1.0, gain))\n            if self.out:\n                v = int(self._master_gain * 16383)\n                self.out.sysex(bytes([0xF0, 0x7F, 0x7F, 0x04, 0x01,\n                                      v & 0x7F, (v >> 7) & 0x7F, 0xF7]))\n\n        def _process_sysex(self, msg):\n            """I SysEx del file vanno inoltrati TALI E QUALI all\'expander: sono\n            loro a selezionare i banchi M-Live e i parametri GS/XG."""\n            if not sysex_abilitato() or not self.out:\n                return\n            try:\n                dati = bytes(msg.data) if hasattr(msg, \'data\') else b\'\'\n                if dati:\n                    self.out.sysex(dati)\n            except Exception:\n                pass\n\n        def _gm_reset(self):\n            """Reset: lo esegue l\'expander, qui si riallinea solo lo stato interno."""\n            if self.out:\n                self.out.sysex(b\'\\xF0\\x7E\\x7F\\x09\\x01\\xF7\')\n            self.channel_bank_msb = [0] * 16\n            self.channel_bank_lsb = [0] * 16\n            self.channel_programs = [0] * 16\n            self.channel_volumes = [100] * 16\n            self.channel_pan = [64] * 16\n            self.channel_expression = [127] * 16\n            self.channel_sustain = [0] * 16\n            self.channel_reverb_send = [40] * 16\n            self.channel_chorus_send = [0] * 16\n            self.active_notes = [0] * 16\n\n        def nome_suono_canale(self, ch):\n            """Nome del suono attivo su un canale (usato dal mixer MIDI)."""\n            try:\n                prog = self.channel_programs[ch]\n                bank = self.channel_bank_msb[ch]\n                return nome_suono_expander(prog, bank, is_drum=(ch == 9))\n            except Exception:\n                return None\n\n        def cleanup(self):\n            try:\n                self.stop()\n            except Exception:\n                pass\n            if self.out:\n                try:\n                    for ch in range(16):\n                        self.synth.cc(ch, 123, 0)\n                        self.synth.cc(ch, 120, 0)\n                except Exception:\n                    pass\n                self.out.chiudi()\n                self.out = None\n            self.synth = None\n            self.initialized = False\n\n    return _ExpanderPlayer\n\n\n# ===================================================================\n#  SINGLETON / PUNTO DI INGRESSO PER KaraDom\n# ===================================================================\n\n_player = None\n_avviso_dato = False\n\n\ndef get_expander_player():\n    """Player MIDI sull\'expander, oppure None se non si deve/può usare.\n\n    None = KaraDom prosegue esattamente come prima (BASS/FluidSynth interni).\n    """\n    global _player, _avviso_dato\n\n    if get_mode() == \'off\':\n        return None\n\n    if _player is not None and _player.initialized:\n        return _player\n\n    porta = detect_expander()\n    if not porta:\n        if not _avviso_dato:\n            _avviso_dato = True\n            print("ℹ️ Expander MIDI non rilevato — uso il SoundFont interno")\n        return None\n\n    try:\n        Classe = _crea_classe()\n        p = Classe(porta)\n        if p.initialize():\n            _player = p\n            return _player\n        return None\n    except Exception as e:\n        print(f"⚠️ Expander: impossibile creare il player ({e}) — uso il SoundFont interno")\n        return None\n\n\ndef is_active():\n    """True se l\'expander sta effettivamente pilotando l\'audio MIDI."""\n    return _player is not None and _player.initialized\n\n\ndef get_active_player():\n    """Il player expander già attivo (senza crearne uno nuovo)."""\n    return _player if is_active() else None\n\n\ndef reset_player():\n    """Chiude l\'expander e dimentica il rilevamento (dopo un cambio di config)."""\n    global _player, _avviso_dato\n    if _player is not None:\n        try:\n            _player.cleanup()\n        except Exception:\n            pass\n    _player = None\n    _avviso_dato = False\n\n\ndef stato():\n    """Riepilogo leggibile — per la finestra di configurazione e il log."""\n    porte = list_ports()\n    porta = detect_expander()\n    return {\n        \'modo\': get_mode(),\n        \'attivo\': is_active(),\n        \'porta_attiva\': _player.nome_porta if is_active() else None,\n        \'porta_rilevata\': porta[\'nome\'] if porta else None,\n        \'porte\': porte,\n        \'sysex\': sysex_abilitato(),\n    }\n\n\ndef prova_suono(device_id=None):\n    """Suona 3 note sull\'expander per verificare che risponda.\n    Se device_id è None usa la porta rilevata/attiva. Ritorna (ok, messaggio)."""\n    import time\n\n    if is_active() and device_id is None:\n        out, propria = _player.out, False\n    else:\n        if device_id is None:\n            porta = detect_expander()\n            if not porta:\n                return False, "Nessun expander rilevato"\n            device_id, nome = porta[\'id\'], porta[\'nome\']\n        else:\n            nome = next((p[\'nome\'] for p in list_ports() if p[\'id\'] == device_id), \'?\')\n        out, propria = _UscitaMIDI(device_id, nome), True\n        if not out.apri():\n            return False, f"Impossibile aprire la porta \'{nome}\'"\n\n    try:\n        out.short(0xB0, 0, 0)          # bank 0\n        out.short(0xC0, 0, 0)          # program 1 = pianoforte\n        out.short(0xB0, 7, 110)        # volume\n        for nota in (60, 64, 67):\n            out.short(0x90, nota, 100)\n            time.sleep(0.25)\n            out.short(0x80, nota, 0)\n        return True, "Note inviate all\'expander"\n    except Exception as e:\n        return False, f"Errore durante il test: {e}"\n    finally:\n        if propria:\n            out.chiudi()\n\n\n# ===================================================================\n#  DIAGNOSTICA DA RIGA DI COMANDO\n#     python -m moduli.expander_midi\n# ===================================================================\n\nif __name__ == \'__main__\':\n    print("=" * 62)\n    print(" DIAGNOSTICA EXPANDER MIDI")\n    print("=" * 62)\n    info = stato()\n    print(f"Modalità configurata : {info[\'modo\']}")\n    print(f"SysEx inoltrati      : {\'sì\' if info[\'sysex\'] else \'no\'}")\n    print(f"\\nPorte MIDI OUT trovate: {len(info[\'porte\'])}")\n    for p in info[\'porte\']:\n        etichetta = {\'software\': \'synth software\', \'loopback\': \'porta virtuale\',\n                     \'mixer\': \'mixer/scheda audio (no suoni)\',\n                     \'expander\': \'HARDWARE\'}.get(p[\'tipo\'], p[\'tipo\'])\n        print(f"  [{p[\'id\']}] {p[\'nome\']:<40} {etichetta} (punteggio {p[\'punteggio\']})")\n    print(f"\\nExpander rilevato    : {info[\'porta_rilevata\'] or \'nessuno\'}")\n\n    if info[\'porta_rilevata\']:\n        print("\\nTest suono in corso...")\n        ok, msg = prova_suono()\n        print(f"  {\'✅\' if ok else \'❌\'} {msg}")\n'

CODICE_STR = '# -*- coding: utf-8 -*-\n"""IL TEMPO DEL MIDI LO TIENE WINDOWS, NON PYTHON.\n\nPerche\' esiste questo file (4 set 2026). Con l\'expander la musica rallentava\nappena il programma si metteva a lavorare: scrivendo nella ricerca, spostandosi\nfra i preferiti, e su un archivio da 400.000 basi bastava poco. Misurato: la\nmusica scendeva al 52% del dovuto, meta\' velocita\'.\n\nLa causa non era una taratura sbagliata ma l\'architettura. Con `midiOutShortMsg`\nogni singola nota deve essere spedita da Python NEL MOMENTO GIUSTO: se il thread\nnon gira - e in Python basta che un altro thread tenga il GIL - la nota esce\ntardi. Nessun aggiustamento del timing puo\' rimediare, perche\' il problema e\'\nche il tempo lo tiene un linguaggio che non puo\' garantirlo.\n\n## Come funziona invece qui\n\nWindows offre `midiStreamOut`: si consegna al driver un BLOCCO di eventi, ognuno\ncol suo tempo, e *"Windows e il dispositivo si occupano di temporizzare ogni\nevento e mandarlo fuori"* (documentazione Microsoft). Il sequencer del driver ha\nrisoluzione di un millisecondo, garantita dal sistema.\n\nQuindi si consegnano un paio di secondi di musica in anticipo e ci si dimentica:\nse la finestra si blocca tre secondi a leggere 400.000 file, il driver continua\na suonare per conto suo. Il GIL diventa irrilevante.\n\n## Cosa NON fa\n\nNon sostituisce il motore: si affianca. Chi lo usa deve sapere che qui i\nmessaggi si CONSEGNANO IN ANTICIPO, quindi le cose che devono avere effetto\nsubito - il volume di un canale che si muove, un canale che si azzittisce, la\ntrasposizione - non passano di qui: per quelle resta la via diretta, che e\'\nimmediata proprio perche\' non e\' programmata.\n\n⚠️ Se qualcosa non va - la porta non supporta lo stream, il driver rifiuta, una\nchiamata fallisce - `apri()` torna False e il chiamante deve continuare col\nmetodo di prima. Non deve mai restare musica muta perche\' questo file ha avuto\nun problema.\n"""\nimport ctypes\nimport sys\nimport struct\nimport threading\nimport time\n\n_MMSYSERR_NOERROR = 0\n_MIDIERR_STILLPLAYING = 65\n\n# ------------------------------------------------------------------\n# ⛔⛔ NESSUNA CHIAMATA AL DRIVER PUO\' INCHIODARE IL PROGRAMMA.\n#     Segnalazione del cliente (13-09): l\'expander si blocca e KaraDom resta\n#     appeso ad aspettarlo. Le chiamate winmm girano sul filo di chi chiama:\n#     se il driver non torna, non torna nessuno. Regola dell\'utente:\n#     «d\'accordo non comincia, ma non deve frizzarsi».\n# ------------------------------------------------------------------\nATTESA_DRIVER = 3.0\n\n\ndef _con_orologio(cosa, dove, fn, secondi):\n    """Chiama il driver in un filo a parte. None se non ha risposto in tempo."""\n    import threading\n    esito = {}\n\n    def lavora():\n        try:\n            esito["ok"] = fn()\n        except Exception as e:\n            esito["err"] = e\n\n    t = threading.Thread(target=lavora, daemon=True, name="midi-%s" % cosa)\n    t.start()\n    t.join(secondi)\n    if t.is_alive():\n        print("⚠️ MIDI: \'%s\' non risponde da %.1f s su \'%s\': lascio stare e "\n              "vado avanti (il programma NON si blocca)" % (cosa, secondi, dove))\n        return None\n    if "err" in esito:\n        raise esito["err"]\n    return esito.get("ok")\n\n\n# proprieta\' dello stream\n_MIDIPROP_SET = 0x80000000\n_MIDIPROP_TIMEDIV = 0x00000001\n_MIDIPROP_TEMPO = 0x00000002\n\n# tipi di evento dentro il blocco (byte alto di dwEvent)\n_MEVT_SHORTMSG = 0x00\n_MEVT_TEMPO = 0x01\n_MEVT_LONGMSG = 0x80        # SysEx dentro lo stream (i banchi M-Live)\n_MEVT_NOP = 0x02\n_MEVT_F_SHORT = 0x00000000\n\n_CALLBACK_NULL = 0x00000000\n\n\nclass _MIDIHDR(ctypes.Structure):\n    _fields_ = [\n        (\'lpData\', ctypes.c_char_p),\n        (\'dwBufferLength\', ctypes.c_ulong),\n        (\'dwBytesRecorded\', ctypes.c_ulong),\n        (\'dwUser\', ctypes.c_size_t),\n        (\'dwFlags\', ctypes.c_ulong),\n        (\'lpNext\', ctypes.c_void_p),\n        (\'reserved\', ctypes.c_size_t),\n        (\'dwOffset\', ctypes.c_ulong),\n        (\'dwReserved\', ctypes.c_size_t * 8),\n    ]\n\n\nclass _MIDIPROPTIMEDIV(ctypes.Structure):\n    _fields_ = [(\'cbStruct\', ctypes.c_ulong), (\'dwTimeDiv\', ctypes.c_ulong)]\n\n\nclass _MIDIPROPTEMPO(ctypes.Structure):\n    _fields_ = [(\'cbStruct\', ctypes.c_ulong), (\'dwTempo\', ctypes.c_ulong)]\n\n\n_FIRME_FATTE = [False]\n\n\ndef _winmm():\n    """winmm con le firme DICHIARATE.\n\n    ⚠️ Senza `argtypes` ctypes passa gli interi a 32 bit, e su Windows a 64 bit\n    gli handle e i puntatori vengono TRONCATI: le chiamate rispondono "tutto\n    bene" ma non fanno niente. Misurato: lo stream si apriva, accettava gli\n    eventi e restava fermo a tick 0. Un\'ora buttata a cercare il difetto\n    altrove, quindi qui si dichiara tutto.\n    """\n    if sys.platform != \'win32\':\n        return None\n    try:\n        mm = ctypes.windll.winmm\n    except Exception:\n        return None\n    if not _FIRME_FATTE[0]:\n        try:\n            H = ctypes.c_void_p            # handle dello stream\n            P = ctypes.POINTER\n            mm.midiStreamOpen.argtypes = [P(H), P(ctypes.c_uint), ctypes.c_uint,\n                                          ctypes.c_void_p, ctypes.c_void_p,\n                                          ctypes.c_uint]\n            mm.midiStreamOpen.restype = ctypes.c_uint\n            for f in ("midiStreamRestart", "midiStreamPause",\n                      "midiStreamStop", "midiStreamClose"):\n                getattr(mm, f).argtypes = [H]\n                getattr(mm, f).restype = ctypes.c_uint\n            mm.midiStreamProperty.argtypes = [H, ctypes.c_void_p, ctypes.c_uint]\n            mm.midiStreamProperty.restype = ctypes.c_uint\n            mm.midiStreamOut.argtypes = [H, ctypes.c_void_p, ctypes.c_uint]\n            mm.midiStreamOut.restype = ctypes.c_uint\n            mm.midiOutPrepareHeader.argtypes = [H, ctypes.c_void_p, ctypes.c_uint]\n            mm.midiOutPrepareHeader.restype = ctypes.c_uint\n            mm.midiOutUnprepareHeader.argtypes = [H, ctypes.c_void_p, ctypes.c_uint]\n            mm.midiOutUnprepareHeader.restype = ctypes.c_uint\n            mm.midiStreamPosition.argtypes = [H, ctypes.c_void_p, ctypes.c_uint]\n            mm.midiStreamPosition.restype = ctypes.c_uint\n            _FIRME_FATTE[0] = True\n        except Exception:\n            pass\n    return mm\n\n\nclass UscitaStream:\n    """Porta MIDI aperta in modalita\' STREAM: il tempo lo tiene il driver.\n\n    Uso:\n        s = UscitaStream(device_id, "Expander")\n        if s.apri(ticks_per_beat=480, tempo=500000):\n            s.accoda([(delta_tick, status, d1, d2), ...])   # anche piu\' volte\n            s.parti()\n            ...\n            s.ferma(); s.chiudi()\n    """\n\n    def __init__(self, device_id, nome=""):\n        self.device_id = int(device_id)\n        self.nome = nome\n        self.aperta = False\n        self._mm = None\n        self._h = None                  # handle dello stream\n        self._lock = threading.Lock()\n        self._blocchi = []              # (MIDIHDR, buffer) ancora in ballo\n        self._errori = 0\n        self._quando_ms = None   # istante dell\'ultimo evento programmato\n        self._riparti = True\n\n    # ---------- apertura ----------\n\n    def apri(self, ticks_per_beat=480, tempo=500000):\n        """Apre lo stream. False se non si puo\': il chiamante usi il metodo vecchio."""\n        mm = _winmm()\n        if mm is None:\n            return False\n        try:\n            h = ctypes.c_void_p()\n            dev = ctypes.c_uint(self.device_id)\n            # ⏱️ con l\'orologio: un expander piantato non deve inchiodare qui\n            #    (13-09, segnalazione del cliente: KaraDom si blocca quando\n            #    l\'expander si blocca). Se il driver non risponde entro il\n            #    tempo, si rinuncia allo stream e si prova l\'invio diretto.\n            rc = _con_orologio(\n                "apertura dello stream", self.nome,\n                lambda: mm.midiStreamOpen(ctypes.byref(h), ctypes.byref(dev),\n                                          1, 0, 0, _CALLBACK_NULL),\n                ATTESA_DRIVER)\n            if rc is None:\n                return False\n            if rc != _MMSYSERR_NOERROR:\n                print("🎹 stream MIDI non disponibile su \'%s\' (codice %d): "\n                      "uso l\'invio diretto" % (self.nome, rc))\n                return False\n            self._mm, self._h = mm, h\n\n            # quanti tick per quarto: gli stessi del file MIDI, cosi\' i tempi\n            # si passano tali e quali senza conversioni\n            td = _MIDIPROPTIMEDIV(ctypes.sizeof(_MIDIPROPTIMEDIV), int(ticks_per_beat))\n            mm.midiStreamProperty(h, ctypes.byref(td),\n                                  _MIDIPROP_SET | _MIDIPROP_TIMEDIV)\n            self.imposta_tempo(tempo)\n            self.aperta = True\n            print("🎹 Expander in modalita\' STREAM: il tempo lo tiene Windows "\n                  "(%s)" % self.nome)\n            return True\n        except Exception as e:\n            print("🎹 stream MIDI non utilizzabile (%s): uso l\'invio diretto" % e)\n            self._h = None\n            return False\n\n    def imposta_tempo(self, tempo_us_per_quarto):\n        """Il tempo del brano, in microsecondi per quarto (come nel file MIDI)."""\n        if self._mm is None or self._h is None:\n            return\n        try:\n            t = _MIDIPROPTEMPO(ctypes.sizeof(_MIDIPROPTEMPO),\n                               int(tempo_us_per_quarto))\n            self._mm.midiStreamProperty(self._h, ctypes.byref(t),\n                                        _MIDIPROP_SET | _MIDIPROP_TEMPO)\n        except Exception:\n            pass\n\n    # ---------- consegna degli eventi ----------\n\n    def accoda(self, eventi):\n        """Consegna al driver un blocco di eventi. (quanti_ne_ha_presi)\n\n        `eventi` = [(delta_tick, status, dato1, dato2)] oppure\n                   (delta_tick, "tempo", microsecondi_per_quarto).\n        `delta_tick` e\' la distanza dall\'evento PRECEDENTE, non un tempo assoluto:\n        e\' il formato che vuole Windows, ed e\' anche quello del file MIDI.\n        """\n        if not self.aperta or not eventi:\n            return 0\n        try:\n            # Il buffer si costruisce byte per byte perche\' gli eventi NON hanno\n            # tutti la stessa misura: un messaggio corto occupa 3 parole da 4\n            # byte, un SysEx occupa quelle 3 piu\' i suoi dati (riempiti fino al\n            # multiplo di 4). Con la vecchia misura fissa "3 parole per evento"\n            # i SysEx non ci stavano - ed erano proprio quelli che scelgono i\n            # banchi M-Live sull\'expander.\n            grezzo = bytearray()\n            for ev in eventi:\n                if len(ev) == 3 and ev[1] == "tempo":\n                    grezzo += struct.pack("<III", int(ev[0]), 0,\n                                          (_MEVT_TEMPO << 24) | (int(ev[2]) & 0xFFFFFF))\n                elif len(ev) == 2 or (len(ev) == 3 and ev[1] == "sysex"):\n                    dati = bytes(ev[-1])\n                    if not dati:\n                        continue\n                    if dati[0] != 0xF0:\n                        dati = bytes([0xF0]) + dati\n                    if dati[-1] != 0xF7:\n                        dati = dati + bytes([0xF7])\n                    grezzo += struct.pack("<III", int(ev[0]), 0,\n                                          (_MEVT_LONGMSG << 24) | (len(dati) & 0xFFFFFF))\n                    grezzo += dati\n                    riempi = (-len(dati)) % 4          # i dati vanno allineati a 4\n                    grezzo += bytes(riempi)\n                else:\n                    dt, st, d1, d2 = ev\n                    grezzo += struct.pack("<III", int(dt), 0,\n                                          (_MEVT_SHORTMSG << 24)\n                                          | (int(st) & 0xFF)\n                                          | ((int(d1) & 0x7F) << 8)\n                                          | ((int(d2) & 0x7F) << 16))\n            if not grezzo:\n                return 0\n            corpo = ctypes.create_string_buffer(bytes(grezzo), len(grezzo))\n\n            hdr = _MIDIHDR()\n            ctypes.memset(ctypes.byref(hdr), 0, ctypes.sizeof(hdr))\n            hdr.lpData = ctypes.cast(corpo, ctypes.c_char_p)\n            hdr.dwBufferLength = hdr.dwBytesRecorded = ctypes.sizeof(corpo)\n\n            with self._lock:\n                rc = self._mm.midiOutPrepareHeader(self._h, ctypes.byref(hdr),\n                                                   ctypes.sizeof(hdr))\n                if rc != _MMSYSERR_NOERROR:\n                    return 0\n                rc = self._mm.midiStreamOut(self._h, ctypes.byref(hdr),\n                                            ctypes.sizeof(hdr))\n                if rc != _MMSYSERR_NOERROR:\n                    self._mm.midiOutUnprepareHeader(self._h, ctypes.byref(hdr),\n                                                    ctypes.sizeof(hdr))\n                    return 0\n                # ⚠️ hdr e corpo vanno TENUTI: il driver ci legge dentro finche\'\n                #    non ha finito. Se il garbage collector se li prende, si\n                #    sente rumore o il programma casca.\n                self._blocchi.append((hdr, corpo))\n            return len(eventi)\n        except Exception as e:\n            self._errori += 1\n            if self._errori <= 3:\n                print("⚠️ stream MIDI: blocco non consegnato (%s)" % e)\n            return 0\n\n\n    # ---------- uso come CRONOMETRO (e\' cosi\' che lo usa l\'expander) ----------\n    #\n    # Il tempo MUSICALE resta al player: e\' lui che sa la velocita\', la\n    # tonalita\', i cambi di tempo del file e il punto in cui si e\' spostato.\n    # Allo stream si chiede una cosa sola, quella che Python non sa fare:\n    # "manda questo messaggio fra tot millisecondi, esatti".\n    #\n    # Per questo si apre con 1000 tick al quarto e un quarto da un secondo:\n    # 1 tick = 1 millisecondo, e non serve nessuna conversione. Cosi\' non c\'e\'\n    # un secondo motore di tempo che possa litigare col primo.\n\n    def apri_a_millisecondi(self):\n        """Apre lo stream tarato perche\' 1 tick valga 1 millisecondo."""\n        ok = self.apri(ticks_per_beat=1000, tempo=1000000)\n        if ok:\n            self._quando_ms = None      # istante dell\'ultimo evento accodato\n        return ok\n\n    def programma(self, eventi, adesso=None):\n        """Accoda messaggi ciascuno col PROPRIO istante di uscita.\n\n        `eventi` = [(istante_in_secondi, status, dato1, dato2)], dove l\'istante\n        e\' letto sullo stesso orologio del chiamante (time.perf_counter).\n        Gli eventi vanno passati in ordine di istante.\n\n        Il driver ragiona per DIFFERENZE fra un messaggio e il successivo,\n        quindi qui si tiene il conto di dove si e\' arrivati e si convertono gli\n        istanti assoluti in differenze.\n\n        ⚠️ Se la coda si e\' svuotata - un silenzio piu\' lungo dell\'anticipo, o\n        il primo evento in assoluto - il driver e\' fermo e riparte da adesso:\n        in quel caso il riferimento si azzera, se no la prima nota dopo il\n        silenzio uscirebbe con tutto il ritardo accumulato.\n        """\n        if not self.aperta or not eventi:\n            return 0\n        if adesso is None:\n            adesso = time.perf_counter()\n\n        if self._quando_ms is None or self.finito():\n            self._quando_ms = adesso * 1000.0\n            self._riparti = True\n\n        pacco = []\n        for ev in eventi:\n            # (istante, status, dato1, dato2)  oppure  (istante, "sysex", dati)\n            if len(ev) == 3 and ev[1] == "sysex":\n                istante, coda = ev[0], ("sysex", ev[2])\n            else:\n                istante, coda = ev[0], (ev[1], ev[2], ev[3])\n            ms = istante * 1000.0\n            delta = ms - self._quando_ms\n            if delta < 0:\n                delta = 0.0             # gia\' scaduto: esca subito\n            intero = int(round(delta))\n            # il resto sotto il millisecondo non si butta: si porta avanti,\n            # se no su mille note si accumulerebbe mezzo secondo di deriva\n            self._quando_ms += intero\n            pacco.append((intero,) + coda)\n\n        n = self.accoda(pacco)\n        if getattr(self, "_riparti", False):\n            self.parti()\n            self._riparti = False\n        return n\n\n    def svuota(self):\n        """Butta via quello che il driver ha ancora in canna.\n\n        Serve quando si SALTA a un altro punto del brano, si mette in pausa o\n        si ferma: le note gia\' consegnate uscirebbero lo stesso - sono nelle\n        mani del driver, non piu\' nelle nostre - e si sentirebbero note del\n        pezzo che si e\' appena lasciato. `midiStreamStop` scarta i blocchi in\n        coda; il riferimento del tempo si azzera, cosi\' alla ripresa si\n        riparte da adesso e non dall\'orario vecchio.\n        """\n        if not self.aperta:\n            return\n        try:\n            self._mm.midiStreamStop(self._h)\n        except Exception:\n            pass\n        self.liberati()\n        self._quando_ms = None\n        self._riparti = True\n\n    def liberati(self):\n        """Quanti blocchi il driver ha finito di suonare (e li si libera)."""\n        if not self.aperta:\n            return 0\n        n = 0\n        with self._lock:\n            restano = []\n            for hdr, corpo in self._blocchi:\n                if hdr.dwFlags & 0x00000001:            # MHDR_DONE\n                    try:\n                        self._mm.midiOutUnprepareHeader(self._h, ctypes.byref(hdr),\n                                                        ctypes.sizeof(hdr))\n                    except Exception:\n                        pass\n                    n += 1\n                else:\n                    restano.append((hdr, corpo))\n            self._blocchi = restano\n        return n\n\n    def finito(self):\n        """True quando il driver ha suonato tutto quello che gli avevamo dato.\n\n        Serve a sapere se la musica e\' arrivata in fondo SENZA chiedere la\n        posizione: `midiStreamPosition` in tick su alcuni driver (il GS\n        Wavetable di Windows fra questi) risponde sempre 0 anche mentre lo\n        stream sta suonando, e fidarsene fa credere fermo cio\' che invece va.\n        Il flag DONE sul blocco, invece, lo alza il driver ed e\' affidabile.\n        """\n        self.liberati()\n        return self.in_coda() == 0\n\n    def in_coda(self):\n        """Quanti blocchi il driver deve ancora suonare."""\n        with self._lock:\n            return len(self._blocchi)\n\n    # ---------- comandi ----------\n\n    def parti(self):\n        if self.aperta:\n            try:\n                self._mm.midiStreamRestart(self._h)\n            except Exception:\n                pass\n\n    def pausa(self):\n        if self.aperta:\n            try:\n                self._mm.midiStreamPause(self._h)\n            except Exception:\n                pass\n\n    def ferma(self):\n        """Interrompe subito: il driver butta via quello che aveva in coda."""\n        if not self.aperta:\n            return\n        try:\n            self._mm.midiStreamStop(self._h)\n        except Exception:\n            pass\n        # tutto quello che era in ballo adesso e\' finito: si libera\n        with self._lock:\n            for hdr, _c in self._blocchi:\n                try:\n                    self._mm.midiOutUnprepareHeader(self._h, ctypes.byref(hdr),\n                                                    ctypes.sizeof(hdr))\n                except Exception:\n                    pass\n            self._blocchi = []\n\n    def chiudi(self):\n        if not self.aperta:\n            return\n        self.ferma()\n        try:\n            # ⏱️ se il driver non risponde si lascia l\'handle e si va avanti:\n            #    meglio una porta non chiusa bene che un programma che non si\n            #    chiude piu\'.\n            _con_orologio("chiusura dello stream", self.nome,\n                          lambda: self._mm.midiStreamClose(self._h),\n                          ATTESA_DRIVER)\n        except Exception:\n            pass\n        self.aperta = False\n        self._h = None\n'


def _installa(nome, codice, tag):
    import types
    import moduli
    import os
    breve = nome.split('.')[-1]
    m = sys.modules.get(nome)
    if m is None:
        m = types.ModuleType(nome)
    m.__package__ = 'moduli'
    if not getattr(m, '__file__', None):
        try:
            dove = os.path.dirname(moduli.__file__)
        except Exception:
            dove = os.path.dirname(os.path.abspath(sys.argv[0]))
        m.__file__ = os.path.join(dove, breve + '.py')
    exec(compile(codice, '<%s>' % tag, 'exec'), m.__dict__)
    sys.modules[nome] = m
    setattr(moduli, breve, m)
    return m


def apply():
    try:
        gia = sys.modules.get('moduli.expander_midi')
        if gia is not None and hasattr(gia, '_UscitaMIDI') \
                and hasattr(gia._UscitaMIDI, '_con_orologio') \
                and not getattr(gia, '_s050', False):
            traccia('il programma lo fa gia da se')
            return True
        _installa('moduli.midi_stream', CODICE_STR, 'patch050_stream')._s050 = True
        m = _installa('moduli.expander_midi', CODICE_EXP, 'patch050_exp')
        m._s050 = True
        traccia('expander: se il driver non risponde si rinuncia alla porta,'
                ' il programma NON si blocca')
        return True
    except Exception as e:
        traccia('non agganciata: %s: %s' % (type(e).__name__, e))
        return False


def revert():
    return False


try:
    apply()
except Exception:
    pass
